-- Sólo esquema public vacío. Baseline previa a V1–V22. No ejecutar remotamente.
BEGIN;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public') THEN RAISE EXCEPTION 'Baseline requiere public sin tablas'; END IF; END $$;
CREATE TABLE tiendas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(100) NOT NULL,subdominio varchar(50) NOT NULL UNIQUE,color_primario varchar(20),color_secundario varchar(20),logo_url text,telefono_soporte varchar(20),whatsapp varchar(20),descripcion_comercial varchar(500),estado varchar(12) NOT NULL DEFAULT 'ACTIVA' CHECK(estado IN ('ACTIVA','PENDIENTE','SUSPENDIDA')),creado_en timestamp DEFAULT now());
CREATE TABLE roles(id_rol integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre_rol varchar(50) NOT NULL UNIQUE);
CREATE TABLE usuarios(id_usuario integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(100) NOT NULL,apellido varchar(100) NOT NULL,correo varchar(150) NOT NULL UNIQUE,password_hash varchar(255) NOT NULL,id_rol integer NOT NULL REFERENCES roles,estado boolean NOT NULL DEFAULT true,tienda_id bigint REFERENCES tiendas,UNIQUE(tienda_id,id_usuario));
CREATE TABLE generos(id_genero integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre_genero varchar(50) NOT NULL UNIQUE,estado boolean NOT NULL DEFAULT true);
CREATE TABLE tallas(id_talla integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre_talla varchar(10) NOT NULL UNIQUE,estado boolean NOT NULL DEFAULT true);
CREATE TABLE categorias(id_categoria integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre_categoria varchar(100) NOT NULL,estado boolean NOT NULL DEFAULT true,tienda_id bigint NOT NULL REFERENCES tiendas,UNIQUE(tienda_id,id_categoria));
CREATE TABLE productos(id_producto integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(150) NOT NULL,descripcion varchar(1000),precio numeric(12,2) NOT NULL,precio_oferta numeric(12,2),id_genero integer NOT NULL REFERENCES generos,id_categoria integer NOT NULL REFERENCES categorias,imagen varchar(255),nuevo boolean NOT NULL DEFAULT false,destacado boolean NOT NULL DEFAULT false,estado boolean NOT NULL DEFAULT true,tienda_id bigint NOT NULL REFERENCES tiendas,FOREIGN KEY(tienda_id,id_categoria) REFERENCES categorias(tienda_id,id_categoria),UNIQUE(tienda_id,id_producto));
CREATE TABLE producto_tallas(id_producto_talla integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_producto integer NOT NULL REFERENCES productos,id_talla integer NOT NULL REFERENCES tallas,stock integer NOT NULL DEFAULT 0 CHECK(stock>=0));
CREATE TABLE producto_imagenes(id_producto_imagen integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_producto integer NOT NULL REFERENCES productos,imagen varchar(255) NOT NULL,orden integer NOT NULL DEFAULT 0);
CREATE TABLE direcciones_envio(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,departamento varchar(100) NOT NULL,provincia varchar(100) NOT NULL,distrito varchar(100) NOT NULL,direccion_exacta varchar(255) NOT NULL,referencia varchar(255),costo_delivery numeric(10,2) NOT NULL);
CREATE TABLE ventas(id_venta integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_usuario integer NOT NULL REFERENCES usuarios,tipo_venta varchar(20),fecha_venta timestamp NOT NULL,subtotal numeric(12,2),costo_delivery numeric(12,2),total numeric(12,2) NOT NULL,estado varchar(50) NOT NULL,estado_pedido varchar(30),medio_pago varchar(50) NOT NULL,id_direccion_envio bigint UNIQUE REFERENCES direcciones_envio,tienda_id bigint NOT NULL REFERENCES tiendas,UNIQUE(tienda_id,id_venta),FOREIGN KEY(tienda_id,id_usuario) REFERENCES usuarios(tienda_id,id_usuario));
CREATE TABLE detalle_venta(id_detalle_venta integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_venta integer NOT NULL REFERENCES ventas,id_producto_talla integer NOT NULL REFERENCES producto_tallas,cantidad integer NOT NULL CHECK(cantidad>0),precio_unitario numeric(12,2) NOT NULL,subtotal numeric(12,2) NOT NULL);
CREATE TABLE home_banner(id_banner integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,etiqueta varchar(100),titulo varchar(200),descripcion varchar(500),texto_boton varchar(100),enlace_boton varchar(255),imagen varchar(255),orden integer NOT NULL,estado boolean NOT NULL DEFAULT true,tienda_id bigint REFERENCES tiendas);
CREATE TABLE home_colecciones(id_coleccion integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,titulo varchar(100),etiqueta varchar(100),texto_boton varchar(100),enlace varchar(255),imagen varchar(255),orden integer NOT NULL,estado boolean NOT NULL DEFAULT true,tienda_id bigint REFERENCES tiendas);
CREATE TABLE clientes_presenciales(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tienda_id bigint REFERENCES tiendas,tipo_documento text NOT NULL,numero_documento text NOT NULL,nombre text,apellido text,telefono text,correo text,CONSTRAINT uk_cliente_presencial_documento UNIQUE(tipo_documento,numero_documento));
CREATE TABLE saas_cancelaciones_cod(tienda_id bigint NOT NULL,id_venta integer NOT NULL,motivo varchar(300) NOT NULL,cancelado_por text NOT NULL,unidades_repuestas integer NOT NULL CHECK(unidades_repuestas>=0),cancelado_en timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tienda_id,id_venta),FOREIGN KEY(tienda_id,id_venta) REFERENCES ventas(tienda_id,id_venta));
CREATE TABLE saas_cobros_contraentrega(tienda_id bigint NOT NULL,id_venta integer NOT NULL,monto numeric(12,2) NOT NULL CHECK(monto>=0),estado text NOT NULL DEFAULT 'PENDIENTE',metodo_cobro text,referencia_cobro text,cobrado_en timestamptz,creado_en timestamptz NOT NULL DEFAULT now(),actualizado_en timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tienda_id,id_venta),FOREIGN KEY(tienda_id,id_venta) REFERENCES ventas(tienda_id,id_venta));
CREATE TABLE saas_envios(id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,tienda_id bigint NOT NULL,id_venta integer NOT NULL,operador text NOT NULL DEFAULT 'PROPIO',modalidad text NOT NULL DEFAULT 'DOMICILIO',estado text NOT NULL DEFAULT 'PENDIENTE',numero_guia text,codigo_rastreo text,observaciones text,creado_en timestamptz NOT NULL DEFAULT now(),actualizado_en timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tienda_id,id_venta),FOREIGN KEY(tienda_id,id_venta) REFERENCES ventas(tienda_id,id_venta));
CREATE TABLE planes_saas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo varchar(50) NOT NULL UNIQUE,nombre varchar(100) NOT NULL,descripcion text,precio_mensual numeric(12,2) NOT NULL CHECK(precio_mensual>=0),moneda char(3) NOT NULL DEFAULT 'PEN',duracion_meses integer NOT NULL CHECK(duracion_meses>0),limite_productos integer,limite_usuarios integer,limite_sucursales integer,beneficios jsonb NOT NULL DEFAULT '[]',activo boolean NOT NULL DEFAULT true,creado_en timestamptz NOT NULL DEFAULT now(),actualizado_en timestamptz NOT NULL DEFAULT now());
CREATE TABLE suscripciones_saas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tienda_id bigint NOT NULL REFERENCES tiendas,plan_id bigint NOT NULL REFERENCES planes_saas,estado varchar(20) NOT NULL CHECK(estado IN ('ACTIVA','PENDIENTE','VENCIDA','CANCELADA')),fecha_inicio date NOT NULL,fecha_fin date NOT NULL CHECK(fecha_fin>fecha_inicio),precio_contratado numeric(12,2) NOT NULL CHECK(precio_contratado>=0),moneda char(3) NOT NULL,creado_en timestamptz NOT NULL DEFAULT now(),actualizado_en timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX suscripciones_activas_tienda ON suscripciones_saas(tienda_id) WHERE estado='ACTIVA';
CREATE TABLE saas_configuracion(clave varchar(100) PRIMARY KEY,valor text NOT NULL,actualizado_en timestamptz NOT NULL DEFAULT now());
CREATE TABLE saas_actividad(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario text NOT NULL,accion text NOT NULL,entidad text NOT NULL,entidad_id text,descripcion text NOT NULL,creado_en timestamptz NOT NULL DEFAULT now());
CREATE TABLE dominios_saas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tienda_id bigint NOT NULL REFERENCES tiendas,dominio varchar(253) NOT NULL UNIQUE,estado text NOT NULL DEFAULT 'PENDIENTE',token_verificacion text NOT NULL,creado_en timestamptz NOT NULL DEFAULT now(),actualizado_en timestamptz NOT NULL DEFAULT now(),verificado_en timestamptz);
CREATE TABLE saas_footer_config(tienda_id bigint PRIMARY KEY REFERENCES tiendas,descripcion text,texto_contacto text,horario text,correo text,facebook_url text,instagram_url text,tiktok_url text,beneficios_activos boolean NOT NULL DEFAULT true,beneficio_envios text,beneficio_pagos text,beneficio_atencion text,newsletter_activo boolean NOT NULL DEFAULT false,newsletter_titulo text,newsletter_descripcion text,texto_legal text,actualizado_en timestamptz NOT NULL DEFAULT now());
COMMIT;

